package com.quotexrealvision.ai; public final class Maths { private Maths(){} public static double mean(double[] a){if(a.length==0)return 0;double s=0;for(double v:a)s+=v;return s/a.length;} public static double stdev(double[] a){if(a.length<2)return 0;double m=mean(a),s=0;for(double v:a){double d=v-m;s+=d*d;}return Math.sqrt(s/(a.length-1));} public static double sigmoid(double z){if(z>=0){double e=Math.exp(-z);return 1/(1+e);}double e=Math.exp(z);return e/(1+e);} }
